import string
def word_frequencies(text: str) -> dict[str, int]:
    text_clean = text.lower().translate(str.maketrans('', '', string.punctuation))
    words = text_clean.split()
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    return counts

