def word_frequencies(text: str) -> dict[str, int]:
    cleaned_text = clean_text(text)
    words = cleaned_text.split()
    word_freq = {}

    for word in words:
        if word in word_freq:
            word_freq[word] += 1
        else:
            word_freq[word] = 1

    return word_freq
```

